using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace EfFixtures.Tests;

public class TotalViewsPerBlogTests : IAsyncLifetime
{
    private SqliteConnection _connection = null!;
    private BlogContext _database = null!;

    public async Task InitializeAsync()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        await _connection.OpenAsync();
        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;
        _database = new BlogContext(options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    [Fact]
    public async Task GivenNoBlogs_WhenGettingTotalViewsPerBlog_ThenResultIsEmpty()
    {
        var totals = await WhenGettingTotalViewsPerBlog();

        Assert.Empty(totals);
    }

    [Fact]
    public async Task GivenBlogWithNoPosts_WhenGettingTotalViewsPerBlog_ThenTotalIsZero()
    {
        await GivenBlog("Empty");

        var totals = await WhenGettingTotalViewsPerBlog();

        ThenTotalsAre(totals, new BlogTotal("Empty", 0));
    }

    [Fact]
    public async Task GivenBlogWithPosts_WhenGettingTotalViewsPerBlog_ThenTotalIsSumOfPostViews()
    {
        await GivenBlog("Tech", 10, 20, 12);

        var totals = await WhenGettingTotalViewsPerBlog();

        ThenTotalsAre(totals, new BlogTotal("Tech", 42));
    }

    [Fact]
    public async Task GivenMultipleBlogs_WhenGettingTotalViewsPerBlog_ThenEachBlogHasItsOwnTotal()
    {
        await GivenBlog("Tech", 10, 5);
        await GivenBlog("Food", 100);

        var totals = await WhenGettingTotalViewsPerBlog();

        ThenTotalsAre(totals, new BlogTotal("Food", 100), new BlogTotal("Tech", 15));
    }

    [Fact]
    public async Task GivenBlogsAddedOutOfOrder_WhenGettingTotalViewsPerBlog_ThenResultsAreOrderedByName()
    {
        await GivenBlog("Charlie", 1);
        await GivenBlog("Alpha", 2);
        await GivenBlog("Bravo", 3);

        var totals = await WhenGettingTotalViewsPerBlog();

        Assert.Equal(new[] { "Alpha", "Bravo", "Charlie" }, totals.Select(total => total.BlogName));
    }

    [Fact]
    public async Task GivenBlogWithContributors_WhenGettingTotalViewsPerBlog_ThenTotalIsNotMultiplied()
    {
        await GivenBlogWithContributors("Tech", 3, 10, 20);

        var totals = await WhenGettingTotalViewsPerBlog();

        ThenTotalsAre(totals, new BlogTotal("Tech", 30));
    }

    [Fact]
    public async Task GivenBlogWithContributorsAndNoPosts_WhenGettingTotalViewsPerBlog_ThenTotalIsZero()
    {
        await GivenBlogWithContributors("Quiet", 2);

        var totals = await WhenGettingTotalViewsPerBlog();

        ThenTotalsAre(totals, new BlogTotal("Quiet", 0));
    }

    [Fact]
    public async Task GivenPostWithZeroViews_WhenGettingTotalViewsPerBlog_ThenTotalIsZero()
    {
        await GivenBlog("Zero", 0, 0);

        var totals = await WhenGettingTotalViewsPerBlog();

        ThenTotalsAre(totals, new BlogTotal("Zero", 0));
    }

    private async Task GivenBlog(string name, params int[] postViews)
    {
        await GivenBlogWithContributors(name, 0, postViews);
    }

    private async Task GivenBlogWithContributors(string name, int contributorCount, params int[] postViews)
    {
        var blog = new Blog
        {
            Name = name,
            Posts = postViews
                .Select((views, index) => new Post { Title = $"{name} post {index}", Views = views })
                .ToList(),
            Contributors = Enumerable.Range(0, contributorCount)
                .Select(index => new Contributor { Name = $"{name} contributor {index}" })
                .ToList()
        };
        _database.Blogs.Add(blog);
        await _database.SaveChangesAsync();
        _database.ChangeTracker.Clear();
    }

    private Task<List<BlogTotal>> WhenGettingTotalViewsPerBlog() =>
        BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

    private static void ThenTotalsAre(List<BlogTotal> actual, params BlogTotal[] expected) =>
        Assert.Equal(expected, actual);
}
