using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class BlogQueriesPopularTitlesTests : IAsyncLifetime
{
    private SqliteConnection _connection = null!;
    private BlogContext _database = null!;

    public async Task InitializeAsync()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        await _connection.OpenAsync();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;
        _database = new BlogContext(options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    private async Task SeedPosts(params (string Title, int Views)[] posts)
    {
        var blog = new Blog { Name = "Blog", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        foreach (var (title, views) in posts)
        {
            blog.Posts.Add(new Post { Title = title, Views = views });
        }
        _database.Blogs.Add(blog);
        await _database.SaveChangesAsync();
    }

    [Fact]
    public async Task GivenNoPosts_WhenGettingPopularTitles_ThenResultIsEmpty()
    {
        var titles = await BlogQueries.PopularTitles(_database, 10, CancellationToken.None);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task GivenPostsAboveAndBelowThreshold_WhenGettingPopularTitles_ThenOnlyPostsAboveThresholdAreReturned()
    {
        await SeedPosts(("Low", 5), ("High", 50), ("Higher", 100));

        var titles = await BlogQueries.PopularTitles(_database, 10, CancellationToken.None);

        Assert.Equal(new[] { "Higher", "High" }, titles);
    }

    [Fact]
    public async Task GivenPostWithViewsEqualToThreshold_WhenGettingPopularTitles_ThenPostIsExcluded()
    {
        await SeedPosts(("Exact", 10), ("Above", 11));

        var titles = await BlogQueries.PopularTitles(_database, 10, CancellationToken.None);

        Assert.Equal(new[] { "Above" }, titles);
    }

    [Fact]
    public async Task GivenPostsInAscendingViewOrder_WhenGettingPopularTitles_ThenTitlesAreOrderedByViewsDescending()
    {
        await SeedPosts(("A", 20), ("B", 30), ("C", 40));

        var titles = await BlogQueries.PopularTitles(_database, 0, CancellationToken.None);

        Assert.Equal(new[] { "C", "B", "A" }, titles);
    }

    [Fact]
    public async Task GivenPostsAcrossBlogs_WhenGettingPopularTitles_ThenTitlesFromAllBlogsAreIncluded()
    {
        var first = new Blog { Name = "First", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        first.Posts.Add(new Post { Title = "FirstPost", Views = 30 });
        var second = new Blog { Name = "Second", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        second.Posts.Add(new Post { Title = "SecondPost", Views = 40 });
        _database.Blogs.AddRange(first, second);
        await _database.SaveChangesAsync();

        var titles = await BlogQueries.PopularTitles(_database, 10, CancellationToken.None);

        Assert.Equal(new[] { "SecondPost", "FirstPost" }, titles);
    }

    [Fact]
    public async Task GivenBlogWithContributors_WhenGettingPopularTitles_ThenEachTitleAppearsOnce()
    {
        var blog = new Blog { Name = "Blog", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        blog.Posts.Add(new Post { Title = "Popular", Views = 100 });
        blog.Contributors.Add(new Contributor { Name = "Alice" });
        blog.Contributors.Add(new Contributor { Name = "Bob" });
        _database.Blogs.Add(blog);
        await _database.SaveChangesAsync();

        var titles = await BlogQueries.PopularTitles(_database, 10, CancellationToken.None);

        Assert.Equal(new[] { "Popular" }, titles);
    }

    [Fact]
    public async Task GivenCancelledToken_WhenGettingPopularTitles_ThenOperationIsCancelled()
    {
        await SeedPosts(("Popular", 100));
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(_database, 10, cancellation.Token));
    }
}
