using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public sealed class BlogQueriesPopularTitlesTests : IDisposable
{
    private readonly SqliteConnection connection;
    private readonly DbContextOptions<BlogContext> options;

    public BlogQueriesPopularTitlesTests()
    {
        connection = new SqliteConnection("DataSource=:memory:");
        connection.Open();
        options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(connection)
            .Options;
        using var context = new BlogContext(options);
        context.Database.EnsureCreated();
    }

    public void Dispose() => connection.Dispose();

    private static Blog GivenBlog(string name, params (string Title, int Views)[] posts)
    {
        var blog = new Blog { Name = name, Posts = new List<Post>(), Contributors = new List<Contributor>() };
        foreach (var (title, views) in posts)
        {
            blog.Posts.Add(new Post { Title = title, Views = views });
        }
        return blog;
    }

    private void GivenSeeded(params Blog[] blogs)
    {
        using var context = new BlogContext(options);
        context.Blogs.AddRange(blogs);
        context.SaveChanges();
    }

    private async Task<List<string>> WhenGettingPopularTitles(int minViews)
    {
        using var context = new BlogContext(options);
        return await BlogQueries.PopularTitles(context, minViews, CancellationToken.None);
    }

    [Fact]
    public async Task GivenNoPosts_WhenGettingPopularTitles_ThenResultIsEmpty()
    {
        var titles = await WhenGettingPopularTitles(0);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task GivenPostsWithVaryingViews_WhenGettingPopularTitles_ThenOnlyPostsAboveMinimumAreReturned()
    {
        GivenSeeded(GivenBlog("Blog", ("Low", 5), ("High", 50), ("Mid", 20)));

        var titles = await WhenGettingPopularTitles(10);

        Assert.Equal(2, titles.Count);
        Assert.DoesNotContain("Low", titles);
    }

    [Fact]
    public async Task GivenPostWithViewsEqualToMinimum_WhenGettingPopularTitles_ThenPostIsExcluded()
    {
        GivenSeeded(GivenBlog("Blog", ("Exact", 10), ("Above", 11)));

        var titles = await WhenGettingPopularTitles(10);

        Assert.Equal(new[] { "Above" }, titles);
    }

    [Fact]
    public async Task GivenPostsWithVaryingViews_WhenGettingPopularTitles_ThenTitlesAreOrderedByViewsDescending()
    {
        GivenSeeded(GivenBlog("Blog", ("Mid", 20), ("High", 50), ("Low", 15)));

        var titles = await WhenGettingPopularTitles(0);

        Assert.Equal(new[] { "High", "Mid", "Low" }, titles);
    }

    [Fact]
    public async Task GivenPostsInMultipleBlogs_WhenGettingPopularTitles_ThenPostsFromAllBlogsAreOrderedTogether()
    {
        GivenSeeded(
            GivenBlog("First", ("A", 30), ("C", 10)),
            GivenBlog("Second", ("B", 20), ("D", 40)));

        var titles = await WhenGettingPopularTitles(0);

        Assert.Equal(new[] { "D", "A", "B", "C" }, titles);
    }

    [Fact]
    public async Task GivenBlogWithContributors_WhenGettingPopularTitles_ThenPostsAreNotDuplicated()
    {
        var blog = GivenBlog("Blog", ("Only", 100));
        blog.Contributors.Add(new Contributor { Name = "Ann" });
        blog.Contributors.Add(new Contributor { Name = "Bob" });
        GivenSeeded(blog);

        var titles = await WhenGettingPopularTitles(0);

        Assert.Equal(new[] { "Only" }, titles);
    }

    [Fact]
    public async Task GivenNoPostAboveMinimum_WhenGettingPopularTitles_ThenResultIsEmpty()
    {
        GivenSeeded(GivenBlog("Blog", ("Low", 1), ("Lower", 2)));

        var titles = await WhenGettingPopularTitles(100);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task GivenCanceledToken_WhenGettingPopularTitles_ThenOperationIsCanceled()
    {
        GivenSeeded(GivenBlog("Blog", ("Post", 10)));
        using var context = new BlogContext(options);
        using var source = new CancellationTokenSource();
        source.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(context, 0, source.Token));
    }
}
