    {
        await GivenBlogWithPosts(("Exact", 10), ("Over", 11));

        var titles = await WhenGettingPopularTitles(minViews: 10);

        Assert.Equal(new[] { "Over" }, titles);
    }

    [Fact]
    public async Task GivenPostsInAscendingViewOrder_WhenGettingPopularTitles_ThenTitlesAreOrderedByViewsDescending()
    {
        await GivenBlogWithPosts(("First", 1), ("Second", 2), ("Third", 3));

        var titles = await WhenGettingPopularTitles(minViews: 0);

        Assert.Equal(new[] { "Third", "Second", "First" }, titles);
    }

    [Fact]
    public async Task GivenPostsAcrossMultipleBlogs_WhenGettingPopularTitles_ThenPostsFromAllBlogsAreIncluded()
    {
        await GivenBlogWithPosts(("A1", 30), ("A2", 10));
        await GivenBlogWithPosts(("B1", 40), ("B2", 5));

        var titles = await WhenGettingPopularTitles(minViews: 8);

        Assert.Equal(new[] { "B1", "A1", "A2" }, titles);
    }

    [Fact]
