        string[] contributorNames)
    {
        var blog = new Blog { Name = "Blog" + Guid.NewGuid() };
        foreach (var (title, views) in posts)
            blog.Posts.Add(new Post { Title = title, Views = views });
        foreach (var name in contributorNames)
            blog.Contributors.Add(new Contributor { Name = name });

        await using var database = new BlogContext(options);
        database.Blogs.Add(blog);
        await database.SaveChangesAsync();
    }

    private async Task<List<string>> WhenGettingPopularTitles(int minViews)
    {
        await using var database = new BlogContext(options);
        return await BlogQueries.PopularTitles(database, minViews, CancellationToken.None);
    }
