    {
        var blog = new Blog { Name = "Blog", Posts = new List<Post>(posts), Contributors = new List<Contributor>() };
        _context.Blogs.Add(blog);
        await _context.SaveChangesAsync();
    }

    private async Task<List<string>> WhenPopularTitles(int minViews)
    {
        return await BlogQueries.PopularTitles(_context, minViews, CancellationToken.None);
