        GivenBlog(database, "Zeta Blog", new[] { 5 });
        GivenBlog(database, "Alpha Blog", new[] { 7, 8 });
        GivenBlog(database, "Middle Blog", new[] { 0 });
        await database.SaveChangesAsync();

        var result = await BlogQueries.TotalViewsPerBlog(database, CancellationToken.None);

        ThenResultEquals(result, new[]
