using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class BlogQueriesTests : IAsyncLifetime
{
    private SqliteConnection _connection;
    private BlogContext _database;

    public Task InitializeAsync()
    {
        _connection = new SqliteConnection("Data Source=:memory:");
        _connection.Open();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        _database = new BlogContext(options);
        _database.Database.EnsureCreated();

        return Task.CompletedTask;
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    private Blog GivenBlog(string name, params (string Title, int Views)[] posts)
    {
        var blog = new Blog { Name = name };
        blog.Posts.AddRange(posts.Select(p => new Post { Title = p.Title, Views = p.Views }));
        return blog;
    }

    [Fact]
    public async Task GivenNoPosts_WhenTotalPostViews_ThenReturnsZero()
    {
        var result = await BlogQueries.TotalPostViews(_database, CancellationToken.None);

        Assert.Equal(0, result);
    }

    [Fact]
    public async Task GivenPostsInOneBlog_WhenTotalPostViews_ThenReturnsSumOfViews()
    {
        GivenPost("First", 3);
        GivenPost("Second", 4);

        var result = await BlogQueries.TotalPostViews(_database, CancellationToken.None);

        Assert.Equal(7, result);
    }

    [Fact]
    public async Task GivenPostsAcrossBlogs_WhenTotalPostViews_ThenReturnsGrandTotal()
    {
        GivenPost("Alpha", 5);
        GivenPost("Beta", 10);
        GivenPost("Gamma", 1);

        var result = await BlogQueries.TotalPostViews(_database, CancellationToken.None);

        Assert.Equal(16, result);
    }

    private void GivenPost(string title, int views)
    {
        var blog = GivenBlog("Blog");
        blog.Posts.Add(new Post { Title = title, Views = views });
        _database.Blogs.Add(blog);
        _database.SaveChanges();
    }
}
